-- WhoIsFree — AI companions (fictional characters). Fully separate from real users:
-- own tables, never in wif_profiles / wif_zones / wif_availability / discover / radar / requests / activities.
-- No location, availability or meeting data exists for companions.

create table if not exists public.wif_companions (
  id uuid primary key default gen_random_uuid(),
  slug text unique not null,
  name text not null,
  age int not null check (age between 21 and 60),
  gender text not null check (gender in ('female', 'male')),
  origin text not null,                 -- fictional backstory only
  occupation jsonb not null,
  tagline jsonb not null,
  bio jsonb not null,
  traits jsonb not null,
  interests text[] not null default '{}',
  languages text[] not null default '{}',
  persona text not null,                -- server-side prompt, never returned to clients
  avatar jsonb not null,
  photos jsonb not null default '[]',
  portrait_path text,                   -- optional admin-uploaded portrait (wif-photos/companions/…)
  active boolean not null default true,
  sort int not null default 0,
  created_at timestamptz not null default now()
);

create table if not exists public.wif_companion_chats (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  companion_id uuid not null references public.wif_companions(id) on delete cascade,
  disclosed_at timestamptz not null default now(),   -- user saw & accepted the AI disclosure
  memory_enabled boolean not null default false,
  memory text,
  memory_updated_at timestamptz,
  turns int not null default 0,
  last_at timestamptz not null default now(),
  unique (user_id, companion_id)
);
create index if not exists wif_companion_chats_user on public.wif_companion_chats (user_id, last_at desc);

create table if not exists public.wif_companion_messages (
  id bigint generated always as identity primary key,
  chat_id uuid not null references public.wif_companion_chats(id) on delete cascade,
  role text not null check (role in ('user', 'assistant')),
  body text not null check (char_length(body) between 1 and 4000),
  created_at timestamptz not null default now()
);
create index if not exists wif_companion_messages_chat on public.wif_companion_messages (chat_id, id desc);

create table if not exists public.wif_ai_usage (
  user_id uuid not null references auth.users(id) on delete cascade,
  day date not null,
  n int not null default 0,
  primary key (user_id, day)
);

alter table public.wif_companions enable row level security;
alter table public.wif_companion_chats enable row level security;
alter table public.wif_companion_messages enable row level security;
alter table public.wif_ai_usage enable row level security;
revoke all on public.wif_companions, public.wif_companion_chats, public.wif_companion_messages, public.wif_ai_usage from anon, authenticated;

create or replace function public.wif_tr(j jsonb, lang text) returns text language sql immutable as $$
  select coalesce(j->>lang, j->>'en')
$$;

create or replace function public.wif_companion_card(c public.wif_companions, lang text, uid uuid) returns jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'id', c.id, 'kind', 'ai', 'name', c.name, 'age', c.age, 'gender', c.gender,
    'occupation', wif_tr(c.occupation, lang), 'tagline', wif_tr(c.tagline, lang),
    'traits', (select coalesce(jsonb_agg(wif_tr(t, lang)), '[]') from jsonb_array_elements(c.traits) t),
    'interests', to_jsonb(c.interests), 'languages', to_jsonb(c.languages),
    'avatar', c.avatar, 'portrait_path', c.portrait_path, 'cover', c.photos->0,
    'chatting', exists (select 1 from wif_companion_chats h where h.user_id = uid and h.companion_id = c.id))
$$;

-- Discover list, personalised by shared interests, stable daily order.
create or replace function public.wif_companions(p_lang text default 'en', p_interest text default null, p_gender text default null, p_offset int default 0, p_limit int default 30)
returns setof jsonb language plpgsql stable security definer set search_path = public as $$
declare uid uuid := auth.uid(); mine text[];
begin
  if uid is null then raise exception 'not_authenticated'; end if;
  select interests into mine from wif_profiles where id = uid;
  return query
    select wif_companion_card(c, p_lang, uid)
    from wif_companions c
    where c.active and (p_interest is null or p_interest = any (c.interests)) and (p_gender is null or c.gender = p_gender)
    order by cardinality(array(select unnest(c.interests) intersect select unnest(coalesce(mine, '{}')))) desc,
             md5(c.id::text || current_date::text || uid::text)
    offset greatest(p_offset, 0) limit least(greatest(p_limit, 1), 50);
end $$;

create or replace function public.wif_companion(p_id uuid, p_lang text default 'en') returns jsonb language plpgsql stable security definer set search_path = public as $$
declare uid uuid := auth.uid(); c wif_companions; h wif_companion_chats;
begin
  if uid is null then raise exception 'not_authenticated'; end if;
  select * into c from wif_companions where id = p_id and active;
  if not found then raise exception 'not_found'; end if;
  select * into h from wif_companion_chats where user_id = uid and companion_id = p_id;
  return wif_companion_card(c, p_lang, uid) || jsonb_build_object(
    'bio', wif_tr(c.bio, p_lang),
    'photos', (select coalesce(jsonb_agg(jsonb_build_object('scene', p->>'scene', 'emoji', p->>'emoji', 'bg', p->'bg', 'caption', wif_tr(p->'caption', p_lang))), '[]') from jsonb_array_elements(c.photos) p),
    'chat', case when h.id is null then null else jsonb_build_object('id', h.id, 'disclosed_at', h.disclosed_at, 'memory_enabled', h.memory_enabled, 'has_memory', h.memory is not null, 'turns', h.turns) end);
end $$;

-- Called only after the user accepted the AI disclosure in the app.
create or replace function public.wif_companion_start(p_id uuid, p_memory boolean default false) returns uuid language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); cid uuid;
begin
  if uid is null then raise exception 'not_authenticated'; end if;
  if not exists (select 1 from wif_companions where id = p_id and active) then raise exception 'not_found'; end if;
  insert into wif_companion_chats (user_id, companion_id, memory_enabled) values (uid, p_id, coalesce(p_memory, false))
  on conflict (user_id, companion_id) do update set memory_enabled = excluded.memory_enabled
  returning id into cid;
  return cid;
end $$;

create or replace function public.wif_companion_messages(p_id uuid, p_before bigint default null, p_limit int default 40) returns setof jsonb language plpgsql stable security definer set search_path = public as $$
declare cid uuid;
begin
  select id into cid from wif_companion_chats where user_id = auth.uid() and companion_id = p_id;
  if cid is null then return; end if;
  return query select jsonb_build_object('id', m.id, 'role', m.role, 'body', m.body, 'created_at', m.created_at)
    from wif_companion_messages m where m.chat_id = cid and (p_before is null or m.id < p_before)
    order by m.id desc limit least(greatest(p_limit, 1), 100);
end $$;

create or replace function public.wif_companion_set_memory(p_id uuid, p_enabled boolean) returns void language plpgsql security definer set search_path = public as $$
begin
  update wif_companion_chats set memory_enabled = p_enabled,
    memory = case when p_enabled then memory else null end,
    memory_updated_at = case when p_enabled then memory_updated_at else null end
  where user_id = auth.uid() and companion_id = p_id;
  if not found then raise exception 'not_found'; end if;
end $$;

create or replace function public.wif_companion_clear(p_id uuid) returns void language plpgsql security definer set search_path = public as $$
declare cid uuid;
begin
  select id into cid from wif_companion_chats where user_id = auth.uid() and companion_id = p_id;
  if cid is null then raise exception 'not_found'; end if;
  delete from wif_companion_messages where chat_id = cid;
  update wif_companion_chats set memory = null, memory_updated_at = null, turns = 0 where id = cid;
end $$;

create or replace function public.wif_companion_inbox(p_lang text default 'en') returns setof jsonb language sql stable security definer set search_path = public as $$
  select jsonb_build_object('id', h.companion_id, 'kind', 'ai', 'name', c.name, 'avatar', c.avatar, 'portrait_path', c.portrait_path,
    'occupation', wif_tr(c.occupation, p_lang), 'last_at', h.last_at,
    'last', (select jsonb_build_object('role', m.role, 'body', m.body) from wif_companion_messages m where m.chat_id = h.id order by m.id desc limit 1))
  from wif_companion_chats h join wif_companions c on c.id = h.companion_id
  where h.user_id = auth.uid() and c.active
  order by h.last_at desc
$$;

-- ---------- service-role only (used by the wif-companion-chat edge function) ----------
create or replace function public.wif_ai_context(p_user uuid, p_companion uuid, p_daily_limit int default 80) returns jsonb language plpgsql security definer set search_path = public as $$
declare h wif_companion_chats; c wif_companions; used int; prof record;
begin
  select * into c from wif_companions where id = p_companion and active;
  if not found then raise exception 'not_found'; end if;
  select * into h from wif_companion_chats where user_id = p_user and companion_id = p_companion;
  if not found then raise exception 'not_disclosed'; end if;
  select coalesce(n, 0) into used from wif_ai_usage where user_id = p_user and day = current_date;
  if coalesce(used, 0) >= p_daily_limit then raise exception 'ai_daily_limit'; end if;
  select split_part(coalesce(display_name, ''), ' ', 1) as first, interests into prof from wif_profiles where id = p_user;
  return jsonb_build_object(
    'chat_id', h.id, 'name', c.name, 'persona', c.persona, 'memory_enabled', h.memory_enabled, 'memory', h.memory, 'turns', h.turns,
    'user_first_name', nullif(prof.first, ''), 'user_interests', to_jsonb(coalesce(prof.interests, '{}')),
    'history', (select coalesce(jsonb_agg(x order by x.id), '[]') from (
      select m.id, m.role, m.body from wif_companion_messages m where m.chat_id = h.id order by m.id desc limit 20) x));
end $$;

create or replace function public.wif_ai_save_turn(p_chat uuid, p_user_text text, p_reply text) returns jsonb language plpgsql security definer set search_path = public as $$
declare uid uuid; um bigint; am bigint; t int;
begin
  update wif_companion_chats set turns = turns + 1, last_at = now() where id = p_chat returning user_id, turns into uid, t;
  if uid is null then raise exception 'not_found'; end if;
  insert into wif_companion_messages (chat_id, role, body) values (p_chat, 'user', left(p_user_text, 4000)) returning id into um;
  insert into wif_companion_messages (chat_id, role, body) values (p_chat, 'assistant', left(p_reply, 4000)) returning id into am;
  insert into wif_ai_usage (user_id, day, n) values (uid, current_date, 1) on conflict (user_id, day) do update set n = wif_ai_usage.n + 1;
  return jsonb_build_object('user_id', um, 'reply_id', am, 'turns', t);
end $$;

create or replace function public.wif_ai_save_memory(p_chat uuid, p_memory text) returns void language sql security definer set search_path = public as $$
  update wif_companion_chats set memory = left(p_memory, 1200), memory_updated_at = now() where id = p_chat and memory_enabled
$$;

-- Account deletion also removes companion chats (auth user row may remain).
create or replace function public.wif_delete_account() returns void language plpgsql security definer set search_path = public as $$
begin
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  update wif_activities set status = 'cancelled' where host_id = auth.uid();
  delete from wif_companion_chats where user_id = auth.uid();
  delete from wif_ai_usage where user_id = auth.uid();
  delete from wif_profiles where id = auth.uid();
end $$;

revoke all on function public.wif_companion_card(public.wif_companions, text, uuid), public.wif_companions(text, text, text, int, int), public.wif_companion(uuid, text),
  public.wif_companion_start(uuid, boolean), public.wif_companion_messages(uuid, bigint, int), public.wif_companion_set_memory(uuid, boolean),
  public.wif_companion_clear(uuid), public.wif_companion_inbox(text), public.wif_ai_context(uuid, uuid, int), public.wif_ai_save_turn(uuid, text, text),
  public.wif_ai_save_memory(uuid, text) from public, anon, authenticated;
grant execute on function public.wif_companions(text, text, text, int, int), public.wif_companion(uuid, text), public.wif_companion_start(uuid, boolean),
  public.wif_companion_messages(uuid, bigint, int), public.wif_companion_set_memory(uuid, boolean), public.wif_companion_clear(uuid),
  public.wif_companion_inbox(text) to authenticated;
grant execute on function public.wif_ai_context(uuid, uuid, int), public.wif_ai_save_turn(uuid, text, text), public.wif_ai_save_memory(uuid, text) to service_role;
